def L(a,z):return '「'+''.join(T[a-1:z])+'」'
B=[
dict(a=1,z=4,star=3,lit=L(1,4),
key=[('有禍了','H1945','hoi','哀哉、有禍了'),('牧人','H7462','roim','牧人、看顧者'),('草場','H4830','marit','牧場、牧養'),('餘剩的','H7611','sheerit','剩下的、餘民'),('招聚','H6908','eqabbets','聚集')],
gram=['**{H4830}**（marit，草場）：「我草場之羊」是詩篇**一百篇三節**的語言：「我們是他的民，也是他草場的羊。」羊**不是牧人的**，是**神的**；牧人**只是受託**。','**{H7611}**（sheerit，餘剩）：這個字是**「餘民」神學的核心**（以賽亞書十章二十一節）。審判之後，**神仍然保留一群人**。**餘民不是靠自己，而是靠神的招聚**。'],
exp=['二十三章從一聲**哀歌式的呼聲**開始：那些殘害、趕散我草場之羊的牧人**有禍了**！這裡的「牧人」，指**猶大的王、官長、祭司和先知**，也就是**一切領袖**。上一章神對王家說話，這一章**延伸到所有帶領百姓的人**。','神的指控很簡單：**你們趕散我的羊群，並沒有看顧他們**。注意那兩個動詞：**趕散**（主動傷害）、**沒有看顧**（被動忽略）。**領袖的罪，有時是做了壞事，更多時候是沒有做好事。**請特別留意：**羊群是「我的」羊群**。牧人只是**受託的管家**。','三、四節是**神自己的承諾**：我要將我羊群中所餘剩的，從各國招聚出來，領他們歸回本圈。**當牧人失職的時候，神自己來作牧人。**這正是**以西結書三十四章**的主題，也是**耶穌說「我是好牧人」**的背景（約十11）。']),
dict(a=5,z=6,star=3,lit=L(5,6),
key=[('苗裔','H6780','tsemakh','苗、新芽'),('公義的','H6662','tsaddiq','公義的、義的'),('智慧','H7919','vehiskil','有智慧、行事通達'),('公平和公義','H4941','mishpat utsedaqah','公平與公義'),('耶和華－我們的義','H6664','YHWH tsidqenu','耶和華是我們的義')],
gram=['**{H6780}**（tsemakh，苗）：這是**彌賽亞稱號**（賽四2；耶三十三15；亞三8、六12）。「苗」是**從砍斷的樹墩長出來的新芽**（賽十一1），是**絕處逢生**的畫面。','**{H6664}**（tsidqenu，我們的義）：這個名字與**西底家**（Tsidqiyyahu，「耶和華是我的義」）**非常相近**。那位王名叫「耶和華是我的義」，卻**不是義**；**真正的義王，要另有其人**。'],
exp=['五、六節是**整卷書最明亮的一節預言**。在一連串對失敗之王的控訴之後，神說：日子將到，我要給大衛興起一個公義的苗裔。**砍斷的樹墩，長出了新芽。**他必掌王權，行事有智慧，在地上施行公平和公義。**這正是約雅敬所沒有做到的（二十二章）。**','六節的名字很特別：**耶和華—我們的義**。這個名字與**西底家**幾乎相同：**那位在位的王，名叫「耶和華是我的義」，卻不義；那位要來的王，名字就是他的本質**。新約把這個名字，應用在**耶穌身上**：祂**成為我們的義**（林前一30）。','請留意：這是**一個人，不是一種制度**。神沒有說「我要改革王室」，而是說**要興起一位**。**真正的盼望，不是更好的制度，而是一位更好的王。**']),
dict(a=7,z=8,star=2,lit=L(7,8),
key=[('永生的耶和華','H2416','khai yhwh','永生的耶和華（起誓用語）'),('領上來','H5927','heeleh','領上來、帶出來'),('北方','H6828','tsafonah','北方'),('後裔','H2233','zera','種子、後裔'),('本地','H127','admatam','自己的土地')],
gram=['**{H6828}**（tsafon，北方）：**巴比倫在以色列的東方，可是軍隊要從北方下來**，所以聖經常以「北方」指**審判之地**。「從北方領回來」，是**神要把被擄的人，從審判之地領回來**。','**{H127}**（adamah，土地）：「他們必住在**本地**」，是**回到自己的土地**。**這是神對流亡者最大的應許。**'],
exp=['七、八節在公義的苗之後，加了**一個很大的盼望**：以後人不再指著「領以色列人從埃及上來」的耶和華起誓，而要指著「從北方領回來」的耶和華起誓。這是說：**第二次出埃及，要比第一次更大**。','出埃及，是**以色列的創世故事**；現在神說，**有一次更大的拯救要來**。**神不會被自己的過去綁住，祂永遠會有更大的作為。**']),
dict(a=9,z=12,star=2,lit=L(9,12),
key=[('發顫','H7363','rakhafu','顫抖、盤旋'),('醉酒','H7910','shikkor','醉漢'),('行淫','H5003','menaafim','姦淫者'),('悲哀','H56','avelah','哀傷、乾枯'),('褻瀆','H2610','khanefu','不敬虔、污穢'),('滑地','H2519','khalaqlaqqot','滑溜之地')],
gram=['**{H7363}**（rakhaf，發顫）：這個字在創世記一章二節，是神的靈「**運行**」在水面上。耶利米說他的骨頭**發顫**，是**神的話在他身上震動**。','**{H2610}**（khanef，褻瀆）：這個字描寫**污染**。連先知帶祭司，**在神的殿中**也都污穢。**最神聖的地方，也被污染了。**'],
exp=['九節的語氣完全改變：**論到那些先知，我心在我裡面憂傷，我骨頭都發顫**。這是**先知的心情**：他看著**同行**的假先知，**不是憤怒，而是心碎**。他說**我像醉酒的人**，就像一個**被神的話打昏了頭的人**。','十到十二節是**對先知與祭司的指控**：**地滿了行淫的人，連先知帶祭司都是褻瀆的，就是在我殿中我也看見他們的惡**。他們的道路必像**黑暗中的滑地**，**仆倒而無法站穩**。']),
dict(a=13,z=15,star=3,lit=L(13,15),
key=[('愚妄','H8604','tiflah','愚昧、不當的事'),('巴力','H1168','habaal','巴力（迦南神明）'),('走錯了路','H8582','vayyatu','使迷路、走偏'),('可憎惡的事','H8186','sharurah','可怕的事'),('茵蔯','H3939','laanah','苦艾'),('苦膽水','H7219','mei rosh','毒水')],
gram=['**{H8604}**（tiflah，愚妄）：**撒馬利亞的先知**的罪，是**藉巴力說預言**；**耶路撒冷的先知**的罪**更重**，是「**可憎惡的事**」（sharurah）。**認識真神的人，若墮落，比不認識的人更危險。**','**{H3939}**（laanah，茵蔯）：茵蔯是**極苦的草**，常與**毒**並用。神說要**讓先知吃苦、喝毒水**，是**他們把毒傳給別人，自己先嘗毒的結果**。'],
exp=['十三、十四節有**一個很重要的對比**：**撒馬利亞的先知**（北國）**藉巴力說預言**，使百姓走錯路——這是**明顯的偶像崇拜**。**耶路撒冷的先知**，更可怕：**他們行姦淫，做事虛妄，又堅固惡人的手，甚至無人回頭離開他的惡**。','「**堅固惡人的手**」是這段**最沉重的一句**：假先知的罪，不只是**自己犯罪**，而是**安慰惡人，叫他們不悔改**。**他們沒有說「不要作惡」，卻說「你們必享平安」。**','所多瑪和蛾摩拉，是**舊約審判的標誌**。神說：**耶路撒冷的居民都像蛾摩拉**。**一座有聖殿的城，與一座被毀的城，在神眼中同樣可怕。**']),
dict(a=16,z=17,star=3,lit=L(16,17),
key=[('虛空','H1891','hevel','虛空、氣息'),('異象','H2377','khazon','異象、啟示'),('自己的心','H3820','libbam','他們的心'),('藐視','H5006','menatsai','藐視、輕蔑'),('平安','H7965','shalom','平安'),('頑梗','H8307','sherirut','頑固、剛硬')],
gram=['**{H1891}**（hevel，虛空）：這就是**傳道書**說「虛空的虛空」的那個字，**意思是「氣息、水蒸氣」**。假先知的信息，**如同呵出的氣，看見了卻抓不住**。','**{H7965}**（shalom，平安）：假先知最愛說的字是**「平安」**。他們說：**你們必享平安**；真先知卻說：**沒有平安**（六14，八11）。**平安是神的恩賜，不是人說了就算。**'],
exp=['十六節給了**我們辨別假先知的第一個原則**：他們所說的異象，是出於自己的心，不是出於耶和華的口。**判準的核心，是來源：話從哪裡來？**','十七節說出**假先知的方法**：他們對藐視神的人說「你們必享平安」，對隨從自己頑梗之心的人說「**必沒有災禍**」。**假先知總是說人想聽的話**。**真先知的話，常常是人不想聽的。**']),
dict(a=18,z=22,star=3,lit=L(18,22),
key=[('會中','H5475','sod','密談、會議、親密的圈子'),('留心聽','H7181','hiqshiv','側耳聽'),('旋風','H5591','sarat','暴風'),('所擬定的','H4209','mezimmot','計畫、心意'),('明白','H995','titbonenu','細細思考、領悟'),('奔跑','H7323','ratsu','奔跑、搶先')],
gram=['**{H5475}**（sod）：這個字是**「祕密會議」、「親近的圈子」**。真先知，是**站在神的sod中**、聽過神的**內部議論**的人（參王上二十二19；伯一6）。**這是先知資格的核心：不是學歷，不是天分，而是聽過神的話。**','**{H7323}**（ruts，奔跑）：假先知**「自己奔跑」**，神**沒有打發**他們。**熱心可以很快，可是方向若不是神給的，跑得越快，離得越遠。**'],
exp=['十八節是一個**修辭的問題**：有誰站在耶和華的會中得以聽見並會悟他的話呢？**答案隱含：假先知沒有。**真先知**不是自封的**，而是**在神面前聽過的人**。','二十一節很直接：**我沒有打發那些先知，他們竟自奔跑；我沒有對他們說話，他們竟自預言**。**神沒有說，他們卻開口。**這是對**一切未經差遣就講神話語的人**的警告。','二十二節給了**第二個判準**：他們若是站在我的會中，就必使我的百姓聽我的話，又使他們回頭離開惡道。**真先知的果效，是使人回頭離開惡，不是使人更舒服。**']),
dict(a=23,z=24,star=3,lit=L(23,24),
key=[('近處','H7138','miqqarov','近處'),('遠處','H7350','mimmerkhaq','遠處'),('隱密處','H4565','bammistarim','隱密的地方'),('藏身','H5641','yissater','隱藏'),('充滿','H4390','male','充滿')],
gram=['**{H4390}**（male，充滿）：「我豈不充滿天地嗎？」是舊約**最清楚的神無所不在**的宣告之一（詩一三九7–10）。**神不只在聖殿，也在人最隱密的角落。**','**{H5641}**（satar，隱藏）：**假先知以為神看不見他的夢與謊言**。神說：**人豈能在隱密處藏身，使我看不見他呢？**'],
exp=['二十三、二十四節是**一個插入的句子，卻很有分量**：我豈為近處的神呢？不也為遠處的神嗎？**神不是一個部落的神，也不是聖殿裡的神**，祂**無處不在**。','這對假先知是**警告**：你以為你在**私下編造的夢、偷偷說的話**，神都看見。對真信徒卻是**安慰**：**你在最隱密的地方哭泣，神也在。**']),
dict(a=25,z=29,star=3,lit=L(25,29),
key=[('做了夢','H2492','khalamti','我做了夢'),('詭詐','H8649','tarmit','詭詐、欺騙'),('忘記','H7911','lehashkiakh','使忘記'),('糠秕','H8401','teven','糠、碎稻草'),('火','H784','esh','火'),('大錘','H6360','pattish','錘子、鎚'),('打碎','H6327','yefotsets','粉碎')],
gram=['**{H8401}**（teven，糠秕）與**{H1250}**（bar，麥子）：糠只有**外殼**，沒有**可吃的實質**。**假先知的夢，是糠；神的話，是麥子。**這不是說夢全是假的，而是**不要把糠當成糧食**。','**{H6360}**（pattish，大錘）與**{H6327}**（patsats，打碎）：神的話像**打碎磐石的大錘**。**這正是十九章打碎瓦瓶的畫面的反面**：神的話**不只是描述，而是做事**。'],
exp=['二十五到二十七節描寫**假先知的伎倆**：他們說「**我做了夢！我做了夢！**」這句話**重複兩次**，像是**想用夢來蓋過一切**。他們的目的是：**使我的百姓忘記我的名**。**他們不是反對神，而是用「夢」取代「神的話」。**','二十八節給了**一個很清楚的比喻**：得夢的先知可以述說那夢；得我話的人可以誠實講說我的話。**糠秕怎能與麥子比較呢？**注意：**聖經沒有禁止人述說夢**，而是說**夢不能與神的話放在同一個位置**。','**二十九節是整章的高潮**：我的話豈不像火，又像能打碎磐石的大錘嗎？**這是對神話語最有力的形容：像火，會燒、會煉、會暖；像錘，會碎、會打。**耶利米二十章說這團火在他的骨中，**這裡說，這團火是神話語的本質。**']),
dict(a=30,z=32,star=2,lit=L(30,32),
key=[('偷竊','H1589','megannevei','偷竊'),('舌頭','H3956','leshonam','舌頭'),('說預言','H5001','vayyinum','宣稱、說神諭'),('幻夢','H2472','khalomot','夢境'),('矜誇','H6350','pakhazutam','輕率、浮誇'),('益處','H3276','yoilu','益處、幫助')],
gram=['**{H1589}**（ganav，偷竊）：假先知**「偷」神的話**：他們從**鄰舍那裡**偷來，不是從神那裡**領受**。**這是抄襲的屬靈版本：不是自己與神見面，而是借用別人的見證、別人的話。**','**{H5001}**（naam，宣稱）：**「耶和華說」**這四個字，是先知**最嚴肅的說話方式**（neum YHWH）。**假先知用舌頭「宣稱」，卻沒有領受。**'],
exp=['三十到三十二節，神三次說「**我必與他們反對**」。這是**很重的宣告**：假先知不是**走錯了路**，而是**站到神的對面**。三個罪名：**偷竊我的言語**、**用舌頭說是耶和華說**、**以幻夢為預言**。','最後一句很重：**他們與這百姓毫無益處**。**假先知的話，聽起來很舒服，卻對人沒有任何幫助。**這是**一個很實際的檢驗：這個信息，是否使人更愛神、更悔改、更成熟？**']),
dict(a=33,z=40,star=3,lit=L(33,40),
key=[('默示','H4853','massa','重擔、默示'),('撇棄','H5203','natashti','丟棄、撇下'),('謬用','H2015','vahafakhtem','扭曲、翻轉'),('永生神','H2416','elohim khayyim','永生的神'),('全然忘記','H5382','venashiti','全然忘記'),('羞恥','H3640','klimmut','羞辱')],
gram=['**{H4853}**（massa，默示／重擔）：這個字有**雙重意思**：**「默示」與「重擔」**。三十三節說「耶和華有甚麼默示（massa）呢？」神說：**你們就是祂的重擔（massa）**。**一個字，兩個意思，神用它做了一個尖銳的文字遊戲。**','**{H2015}**（hafakh，翻轉）：「謬用永生神的言語」是**把神的話翻轉過來**，**把嚴肅的話變成口頭禪**。**一句話常常說，它的重量就被磨掉了。**'],
exp=['最後一段是**一個很特別的文字遊戲**：「默示」（massa）同時是「**重擔**」。百姓問先知：**耶和華有甚麼默示呢？**意思是在問「神的重擔」。神說：**你們就是我的重擔，我要撇棄你們。**','三十六節說：**你們不可再提「耶和華的默示」**，**因為你們謬用永生神的言語**。他們**把神的話當作口頭禪**，**每次說「神說」，卻沒有人真的在聽**。**這是對一切「屬靈詞彙過度使用」的警告**。','最後兩節（三十九、四十）很沉重：**我必全然忘記你們，將你們撇棄**，**使永遠的凌辱和長久的羞恥臨到你們**。**神對輕忽祂的話的人，說了這樣重的話。**可是請記得：**這一章的開頭，是「我要招聚我羊群的餘民」，結尾的審判，與開頭的盼望，同樣真實。**（見議題）']),
]
